"use client";

import { useEffect, useRef, useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import type { FeedbackSubmissionV1 } from "@techlocal/feedback-core";
import {
  ArrowLeft,
  Bug,
  ChevronLeft,
  ChevronRight,
  ImageIcon,
  Inbox,
  Lightbulb,
  Loader2,
  RefreshCw,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group";
import {
  Empty,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/components/ui/empty";
import { cn } from "@/lib/utils";
import {
  FeedbackReviewActions,
  type SaveFeedbackReview,
  type loadFeedbackHistory,
} from "./FeedbackReviewActions";
import {
  initialReview,
  reviewStatuses,
  type FeedbackReview,
} from "@/lib/feedback-kit/review";
import { FeedbackInfo } from "./FeedbackInfo";

export type FeedbackInboxReport = {
  id: string;
  createdAt: string;
  submission: FeedbackSubmissionV1;
  review?: FeedbackReview;
  attachments: Array<{ id: string; privateRef: string }>;
};

function date(value: string, detailed = false) {
  return new Intl.DateTimeFormat(undefined, {
    day: "numeric",
    month: "short",
    ...(detailed
      ? { year: "numeric", hour: "2-digit", minute: "2-digit" }
      : {}),
  }).format(new Date(value));
}

export function FeedbackInbox({
  reports,
  page,
  total,
  saveReview,
  loadHistory,
  startWork,
  loadRun,
  cancelWork,
}: {
  reports: FeedbackInboxReport[];
  page: number;
  total: number;
  saveReview?: SaveFeedbackReview;
  loadHistory?: typeof loadFeedbackHistory;
  startWork?: typeof import("@/lib/feedback-kit/runs").startFeedbackWork;
  loadRun?: typeof import("@/lib/feedback-kit/runs").loadFeedbackRun;
  cancelWork?: typeof import("@/lib/feedback-kit/runs").cancelFeedbackWork;
}) {
  const router = useRouter();
  const [locked, setLocked] = useState(false);
  const [reviews, setReviews] = useState<Record<string, FeedbackReview>>({});
  const [reviewFilter, setReviewFilter] = useState("all");
  function currentReview(report: FeedbackInboxReport) {
    return (
      reviews[report.id] ??
      report.review ??
      initialReview(report.submission.kind)
    );
  }
  const [desktop, setDesktop] = useState(false);
  useEffect(() => {
    const media = window.matchMedia("(min-width: 1024px)");
    const update = () => setDesktop(media.matches);
    update();
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);
  const [pending, startTransition] = useTransition();
  const [query, setQuery] = useState("");
  const [kind, setKind] = useState("all");
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const selectedButton = useRef<HTMLButtonElement | null>(null);
  const detailHeading = useRef<HTMLHeadingElement | null>(null);
  const search = query.trim().toLocaleLowerCase();
  const filtered = reports.filter(
    (report) =>
      (kind === "all" || currentReview(report).kind === kind) &&
      (reviewFilter === "all" ||
        (reviewFilter === "open"
          ? currentReview(report).status !== "closed"
          : currentReview(report).status === reviewFilter)) &&
      `${currentReview(report).title} ${report.submission.description} ${report.submission.context.screen} ${report.id}`
        .toLocaleLowerCase()
        .includes(search),
  );
  const selected = filtered.find(({ id }) => id === selectedId) ?? filtered[0];
  const pages = Math.max(1, Math.ceil(total / 50));
  const clear = () => {
    setQuery("");
    setKind("all");
    setReviewFilter("all");
    setSelectedId(null);
  };
  function navigate(next: number) {
    if (pending || locked) return;
    startTransition(() =>
      router.push(`/admin/feedback?page=${next}`, { scroll: false }),
    );
  }

  return (
    <div
      className="flex min-w-0 flex-col gap-5 text-foreground"
      aria-busy={pending}
    >
      <header className="flex items-center justify-between gap-3">
        <div className="flex items-baseline gap-3">
          <h1 className="text-3xl font-semibold tracking-tight">Feedback</h1>
          <span className="text-sm tabular-nums text-muted-foreground">
            {total}
          </span>
        </div>
        <div className="flex items-center gap-1">
          <FeedbackInfo label="About the review inbox">
            Tester pilot. Private images; access is logged. Manual review only.
            Notes and edits are private to reviewers. Closing a report doesn’t
            verify a released fix.
          </FeedbackInfo>
          <Button
            type="button"
            variant="ghost"
            size="icon"
            className="size-11"
            aria-label="Refresh inbox"
            disabled={pending || locked}
            onClick={() => startTransition(() => router.refresh())}
          >
            {pending ? (
              <Loader2
                className="animate-spin motion-reduce:animate-none"
                aria-hidden="true"
              />
            ) : (
              <RefreshCw aria-hidden="true" />
            )}
          </Button>
        </div>
      </header>

      <div
        className={cn(
          "flex flex-wrap items-center gap-3",
          selectedId && selected && "hidden lg:flex",
        )}
      >
        <Input
          type="search"
          disabled={locked}
          value={query}
          onChange={(event) => {
            setQuery(event.target.value);
            setSelectedId(null);
          }}
          aria-label={
            pages > 1 ? "Search this page of feedback" : "Search feedback"
          }
          placeholder={pages > 1 ? "Search this page…" : "Search feedback…"}
          className="min-h-11 sm:max-w-sm"
        />
        <ToggleGroup
          type="single"
          disabled={locked}
          value={kind}
          onValueChange={(value) => {
            if (value) {
              setKind(value);
              setSelectedId(null);
            }
          }}
          aria-label="Filter feedback"
          className="justify-start gap-1"
        >
          <ToggleGroupItem value="all" className="min-h-11 px-4">
            All
          </ToggleGroupItem>
          <ToggleGroupItem value="bug" className="min-h-11 px-4">
            Bugs
          </ToggleGroupItem>
          <ToggleGroupItem value="suggestion" className="min-h-11 px-4">
            Ideas
          </ToggleGroupItem>
        </ToggleGroup>
        <div className="w-40 shrink-0">
          <Select
            value={reviewFilter}
            disabled={locked}
            onValueChange={(value) => {
              setReviewFilter(value);
              setSelectedId(null);
            }}
          >
            <SelectTrigger
              aria-label="Filter by review status"
              className="min-h-11 w-auto min-w-36"
            >
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectGroup>
                <SelectItem
                  className="rounded-[calc(var(--radius)-0.25rem)]"
                  value="all"
                >
                  All statuses
                </SelectItem>
                <SelectItem
                  className="rounded-[calc(var(--radius)-0.25rem)]"
                  value="open"
                >
                  Open
                </SelectItem>
                {Object.entries(reviewStatuses).map(([value, label]) => (
                  <SelectItem
                    className="rounded-[calc(var(--radius)-0.25rem)]"
                    key={value}
                    value={value}
                  >
                    {label}
                  </SelectItem>
                ))}
              </SelectGroup>
            </SelectContent>
          </Select>
        </div>
      </div>

      <div className="grid min-w-0 overflow-hidden rounded-[var(--radius)] border border-border bg-background lg:h-[min(640px,60dvh)] lg:min-h-[420px] lg:grid-cols-[minmax(240px,0.8fr)_minmax(0,1.4fr)]">
        <section
          aria-label="Reports"
          className={cn(
            "min-w-0 overflow-y-auto lg:border-r lg:border-border",
            selectedId && selected ? "hidden lg:block" : "block",
            !selected && "lg:col-span-2 lg:border-r-0",
          )}
        >
          {!filtered.length ? (
            <Empty className="min-h-72">
              <EmptyHeader>
                <EmptyMedia variant="icon">
                  <Inbox aria-hidden="true" />
                </EmptyMedia>
                <EmptyTitle>
                  {reports.length ? "No matches" : "No feedback yet"}
                </EmptyTitle>
              </EmptyHeader>
              {query || kind !== "all" || reviewFilter !== "all" ? (
                <Button variant="outline" onClick={clear}>
                  Clear filters
                </Button>
              ) : null}
            </Empty>
          ) : (
            <ul className="divide-y divide-border">
              {filtered.map((report) => {
                const Icon =
                  currentReview(report).kind === "bug" ? Bug : Lightbulb;
                const label =
                  currentReview(report).kind === "bug" ? "bug" : "idea";
                const preview =
                  currentReview(report).title ||
                  report.submission.description.trim() ||
                  "Image feedback";
                return (
                  <li key={report.id}>
                    <button
                      type="button"
                      disabled={locked}
                      aria-label={`Open ${label}: ${preview}`}
                      aria-current={
                        selected?.id === report.id ? "true" : undefined
                      }
                      aria-controls="feedback-detail"
                      className={cn(
                        "flex w-full flex-col gap-3 p-4 text-left transition-colors hover:bg-muted/50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring motion-reduce:transition-none",
                        selected?.id === report.id && "bg-muted/60",
                      )}
                      onClick={(event) => {
                        selectedButton.current = event.currentTarget;
                        setSelectedId(report.id);
                        requestAnimationFrame(() => {
                          if (window.matchMedia("(max-width: 1023px)").matches)
                            detailHeading.current?.focus();
                        });
                      }}
                    >
                      <span className="flex items-center justify-between gap-3 text-xs text-muted-foreground">
                        <span className="flex items-center gap-2">
                          <Icon className="size-4" aria-hidden="true" />
                          {label === "bug" ? "Bug" : "Idea"}
                        </span>
                        <time dateTime={report.createdAt}>
                          {date(report.createdAt)}
                        </time>
                      </span>
                      {currentReview(report).status !== "needs_review" ? (
                        <span className="text-xs text-muted-foreground">
                          {reviewStatuses[currentReview(report).status]}
                        </span>
                      ) : null}
                      <span className="line-clamp-2 break-words text-sm leading-6">
                        {preview}
                      </span>
                      {report.submission.screenshots.length ? (
                        <span className="flex items-center gap-1 text-xs text-muted-foreground">
                          <ImageIcon className="size-3.5" aria-hidden="true" />
                          {report.submission.screenshots.length}
                          <span className="sr-only">attachments</span>
                        </span>
                      ) : null}
                    </button>
                  </li>
                );
              })}
            </ul>
          )}
        </section>

        <section
          id="feedback-detail"
          aria-label="Selected report"
          className={cn(
            "min-w-0 overflow-y-auto p-5 sm:p-7",
            selectedId && selected ? "block" : "hidden lg:block",
            !selected && "lg:hidden",
          )}
        >
          {selected ? (
            <article key={selected.id} className="flex min-w-0 flex-col gap-6">
              <Button
                variant="ghost"
                disabled={locked}
                className="-ml-3 min-h-11 self-start lg:hidden"
                onClick={() => {
                  setSelectedId(null);
                  requestAnimationFrame(() => selectedButton.current?.focus());
                }}
              >
                <ArrowLeft data-icon="inline-start" /> Back
              </Button>
              <div className="flex flex-wrap items-start justify-between gap-3">
                <div className="flex min-w-0 flex-col gap-1">
                  <h2
                    ref={detailHeading}
                    tabIndex={-1}
                    className="break-words text-xl font-semibold focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                  >
                    {currentReview(selected).title ||
                      (currentReview(selected).kind === "bug"
                        ? "Bug report"
                        : "Idea")}
                  </h2>
                  <time
                    dateTime={selected.createdAt}
                    className="text-xs text-muted-foreground"
                  >
                    {date(selected.createdAt, true)}
                  </time>
                </div>
              </div>
              <FeedbackReviewActions
                key={selected.id}
                id={selected.id}
                review={currentReview(selected)}
                onLockChange={setLocked}
                saveReview={saveReview}
                loadHistory={loadHistory}
                startWork={startWork}
                loadRun={loadRun}
                cancelWork={cancelWork}
                onSaved={(value) =>
                  setReviews((previous) => ({
                    ...previous,
                    [selected.id]: value,
                  }))
                }
              />
              <div className="flex flex-col gap-1">
                <h3 className="text-xs font-medium text-muted-foreground">
                  Original feedback
                </h3>
                <p
                  data-testid="feedback-original"
                  className="whitespace-pre-wrap break-words text-sm leading-7"
                >
                  {selected.submission.description || "Image feedback"}
                </p>
              </div>
              <dl className="grid min-w-0 grid-cols-[auto_minmax(0,1fr)] gap-x-4 gap-y-2 text-xs">
                <dt className="text-muted-foreground">Screen</dt>
                <dd className="break-all">
                  {selected.submission.context.screen}
                </dd>
                <dt className="text-muted-foreground">Release</dt>
                <dd className="break-all">
                  {selected.submission.observedRelease.commitSha?.slice(0, 8) ??
                    selected.submission.observedRelease.channel ??
                    "Unknown"}
                </dd>
                <dt className="text-muted-foreground">Ref</dt>
                <dd className="break-all">{selected.id.slice(0, 8)}</dd>
              </dl>
              {(desktop || selectedId
                ? selected.submission.screenshots
                : []
              ).map((shot) => {
                const attachment = selected.attachments.find(
                  (value) => value.privateRef === shot.privateRef,
                );
                return attachment ? (
                  <figure
                    key={attachment.id}
                    className="flex min-w-0 flex-col gap-3"
                  >
                    <div className="relative w-fit max-w-full overflow-hidden rounded-[calc(var(--radius)-0.25rem)] border border-border">
                      {/* Private, authenticated and audited endpoint; bypass public image optimisation. */}
                      {/* eslint-disable-next-line @next/next/no-img-element */}
                      <img
                        src={`/api/feedback-kit/attachments/${attachment.id}`}
                        alt="Feedback attachment"
                        loading="lazy"
                        decoding="async"
                        width={shot.width}
                        height={shot.height}
                        className="h-auto max-h-96 w-auto max-w-full"
                      />
                      {shot.annotations.map((note, index) => (
                        <span
                          key={index}
                          aria-hidden="true"
                          className="pointer-events-none absolute border-2 border-primary bg-primary/10"
                          style={{
                            left: `${note.x * 100}%`,
                            top: `${note.y * 100}%`,
                            width: `${note.width * 100}%`,
                            height: `${note.height * 100}%`,
                          }}
                        />
                      ))}
                    </div>
                    {shot.annotations.length ? (
                      <figcaption className="flex flex-col gap-2">
                        {shot.annotations.map((note, index) => (
                          <p
                            key={index}
                            className="whitespace-pre-wrap break-words text-sm text-muted-foreground"
                          >
                            {note.note}
                          </p>
                        ))}
                      </figcaption>
                    ) : null}
                  </figure>
                ) : null;
              })}
            </article>
          ) : null}
        </section>
      </div>
      <footer className="flex items-center justify-between gap-3 text-xs text-muted-foreground">
        <span role="status">
          {filtered.length} {filtered.length === 1 ? "report" : "reports"}
          {pages > 1 ? ` · Page ${page} of ${pages}` : ""}
        </span>
        {pages > 1 ? (
          <nav aria-label="Feedback pages" className="flex gap-1">
            <Button
              variant="outline"
              size="icon"
              className="size-11"
              aria-label="Previous page"
              disabled={page <= 1 || pending || locked}
              onClick={() => navigate(page - 1)}
            >
              <ChevronLeft aria-hidden="true" />
            </Button>
            <Button
              variant="outline"
              size="icon"
              className="size-11"
              aria-label="Next page"
              disabled={page >= pages || pending || locked}
              onClick={() => navigate(page + 1)}
            >
              <ChevronRight aria-hidden="true" />
            </Button>
          </nav>
        ) : null}
      </footer>
    </div>
  );
}

"use client";
import { useEffect, useRef, useState } from "react";
import {
  History,
  Loader2,
  MessageSquarePlus,
  Play,
  Square,
  ExternalLink,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import {
  Field,
  FieldError,
  FieldGroup,
  FieldLabel,
} from "@/components/ui/field";
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Drawer,
  DrawerContent,
  DrawerDescription,
  DrawerTitle,
} from "@/components/ui/drawer";
import { FeedbackInfo } from "./FeedbackInfo";
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group";
import {
  feedbackModels,
  feedbackReasoningLevels,
  reviewStatuses,
  saveFeedbackReview,
  type FeedbackReview,
  type FeedbackReviewDraft,
  type FeedbackReviewHistory,
} from "@/lib/feedback-kit/review";

import {
  startFeedbackWork,
  loadFeedbackRun,
  cancelFeedbackWork,
  runActive,
  type FeedbackRun,
} from "@/lib/feedback-kit/runs";
export type SaveFeedbackReview = typeof saveFeedbackReview;
export async function loadFeedbackHistory(
  id: string,
): Promise<FeedbackReviewHistory[]> {
  const response = await fetch(`/api/feedback-kit/reports/${id}/review`, {
    cache: "no-store",
    signal: AbortSignal.timeout(15000),
  });
  if (!response.ok) throw new Error("Couldn’t load history. Try again.");
  return response.json();
}
export function FeedbackReviewActions({
  id,
  review,
  onSaved,
  onLockChange,
  saveReview = saveFeedbackReview,
  loadHistory = loadFeedbackHistory,
  startWork = startFeedbackWork,
  loadRun = loadFeedbackRun,
  cancelWork = cancelFeedbackWork,
}: {
  id: string;
  review: FeedbackReview;
  onSaved: (review: FeedbackReview) => void;
  onLockChange?: (locked: boolean) => void;
  saveReview?: SaveFeedbackReview;
  loadHistory?: typeof loadFeedbackHistory;
  startWork?: typeof startFeedbackWork;
  loadRun?: typeof loadFeedbackRun;
  cancelWork?: typeof cancelFeedbackWork;
}) {
  const [run, setRun] = useState<FeedbackRun | null>(null);
  const [runError, setRunError] = useState<string | null>(null);
  const requestKey = useRef<{ key: string; fingerprint: string } | null>(null);
  useEffect(() => {
    let live = true;
    let timer: ReturnType<typeof setTimeout>;
    const refresh = async () => {
      if (document.visibilityState === "hidden") {
        timer = setTimeout(refresh, 5000);
        return;
      }
      try {
        const next = await loadRun(id);
        if (live) {
          setRun((current) =>
            !current ||
            (next &&
              Date.parse(next.updated_at) >= Date.parse(current.updated_at))
              ? next
              : current,
          );
          setRunError(null);
        }
      } catch {
        if (live) setRunError("Couldn’t check work.");
      }
      if (live) timer = setTimeout(refresh, 5000);
    };
    void refresh();
    return () => {
      live = false;
      clearTimeout(timer);
    };
  }, [id, loadRun]);
  const active = runActive(run);
  const [mode, setMode] = useState<"context" | "start" | null>(null);
  const [mobile, setMobile] = useState(false);
  useEffect(() => {
    const media = window.matchMedia("(max-width: 767px)");
    const update = () => setMobile(media.matches);
    update();
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);
  const [draft, setDraft] = useState<FeedbackReviewDraft>(review);
  const [busy, setBusy] = useState(false);
  const guard = useRef(false);
  const trigger = useRef<HTMLButtonElement | null>(null);
  const heading = useRef<HTMLHeadingElement | null>(null);
  const guidanceOpen = useRef(false);
  const [error, setError] = useState<string | null>(null);
  const [saved, setSaved] = useState(false);
  const [history, setHistory] = useState<FeedbackReviewHistory[] | null>(null);
  const [historyOpen, setHistoryOpen] = useState(false);
  const [historyBusy, setHistoryBusy] = useState(false);
  const [historyError, setHistoryError] = useState<string | null>(null);
  useEffect(() => {
    onLockChange?.(mode !== null || busy);
  }, [mode, busy, onLockChange]);
  useEffect(() => () => onLockChange?.(false), [onLockChange]);
  async function save(value: FeedbackReviewDraft) {
    if (guard.current) return;
    guard.current = true;
    setBusy(true);
    setError(null);
    setSaved(false);
    // Never send the immutable submission, actor identity, or client release claims.
    const { title, kind, status, notes, model, reasoningEffort, subagents } =
      value;
    try {
      const next = await saveReview(
        id,
        { title, kind, status, notes, model, reasoningEffort, subagents },
        review.revision,
      );
      onSaved(next);
      setMode(null);
      setSaved(true);
      setHistory(null);
      setHistoryOpen(false);
    } catch (reason) {
      setError(
        reason instanceof Error
          ? reason.message
          : "Couldn’t save changes. Try again.",
      );
    } finally {
      guard.current = false;
      setBusy(false);
    }
  }
  async function launch() {
    if (guard.current || active) return;
    guard.current = true;
    setBusy(true);
    setError(null);
    setSaved(false);
    const { title, kind, status, notes, model, reasoningEffort, subagents } =
      draft;
    const value = {
      title,
      kind,
      status,
      notes,
      model,
      reasoningEffort,
      subagents,
    };
    const fingerprint = JSON.stringify({
      id,
      value,
      revision: review.revision,
    });
    if (requestKey.current?.fingerprint !== fingerprint)
      requestKey.current = { key: crypto.randomUUID(), fingerprint };
    try {
      const receipt = await startWork(
        id,
        value,
        review.revision,
        requestKey.current.key,
      );
      onSaved(receipt.review);
      setRun(receipt.run);
      setRunError(null);
      setMode(null);
      setHistory(null);
      setHistoryOpen(false);
    } catch (reason) {
      setError(
        reason instanceof Error
          ? reason.message
          : "Couldn’t start work. Try again.",
      );
    } finally {
      guard.current = false;
      setBusy(false);
    }
  }
  async function stop() {
    if (guard.current || !run) return;
    guard.current = true;
    setBusy(true);
    setError(null);
    try {
      await cancelWork(id, run.id);
      setRun(await loadRun(id));
    } catch (reason) {
      setError(
        reason instanceof Error ? reason.message : "Couldn’t stop work.",
      );
    } finally {
      guard.current = false;
      setBusy(false);
    }
  }
  async function showHistory() {
    if (historyBusy) return;
    if (historyOpen) {
      setHistoryOpen(false);
      return;
    }
    setHistoryOpen(true);
    if (history) return;
    await fetchHistory();
  }
  async function fetchHistory() {
    setHistoryBusy(true);
    setHistoryError(null);
    try {
      setHistory(await loadHistory(id));
    } catch {
      setHistoryError("Couldn’t load history. Try again.");
    } finally {
      setHistoryBusy(false);
    }
  }
  const dirty = (
    ["notes", "model", "reasoningEffort", "subagents"] as const
  ).some((field) => draft[field] !== review[field]);
  function open(mode: "context" | "start", button: HTMLButtonElement) {
    guidanceOpen.current = false;
    trigger.current = button;
    setDraft(review);
    setMode(mode);
    setError(null);
    setSaved(false);
  }
  const Title = mobile ? DrawerTitle : DialogTitle;
  const Description = mobile ? DrawerDescription : DialogDescription;
  const form = (
    <form
      className="flex flex-col gap-5"
      aria-busy={busy}
      onSubmit={(event) => {
        event.preventDefault();
        if (mode === "start") void launch();
        else void save(draft);
      }}
    >
      <div className="flex flex-col gap-2 pr-8">
        <Title ref={heading} tabIndex={-1}>
          {mode === "start" ? "Start work" : "Report context"}
        </Title>
        <Description className="sr-only">
          Add context and instructions without changing the original feedback.
        </Description>
      </div>
      <FieldGroup className="gap-4">
        {mode === "start" ? (
          <FieldGroup className="grid grid-cols-2 gap-4">
            <Field>
              <FieldLabel htmlFor="feedback-work-model">Model</FieldLabel>
              <Select
                value={draft.model}
                disabled={busy}
                onValueChange={(model) =>
                  setDraft({
                    ...draft,
                    model: model as FeedbackReviewDraft["model"],
                    reasoningEffort:
                      model === "gpt-6-luna" &&
                      draft.reasoningEffort === "ultra"
                        ? "max"
                        : draft.reasoningEffort,
                  })
                }
              >
                <SelectTrigger id="feedback-work-model" className="min-h-11">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectGroup>
                    {Object.entries(feedbackModels).map(([value, label]) => (
                      <SelectItem
                        key={value}
                        value={value}
                        className="rounded-[calc(var(--radius)-0.25rem)]"
                      >
                        {label}
                      </SelectItem>
                    ))}
                  </SelectGroup>
                </SelectContent>
              </Select>
            </Field>
            <Field>
              <FieldLabel htmlFor="feedback-work-reasoning">
                Reasoning
              </FieldLabel>
              <Select
                value={draft.reasoningEffort}
                disabled={busy}
                onValueChange={(value) =>
                  setDraft({
                    ...draft,
                    reasoningEffort:
                      value as FeedbackReviewDraft["reasoningEffort"],
                  })
                }
              >
                <SelectTrigger
                  id="feedback-work-reasoning"
                  className="min-h-11"
                >
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectGroup>
                    {Object.entries(feedbackReasoningLevels)
                      .filter(
                        ([value]) =>
                          draft.model !== "gpt-6-luna" || value !== "ultra",
                      )
                      .map(([value, label]) => (
                        <SelectItem
                          key={value}
                          value={value}
                          className="rounded-[calc(var(--radius)-0.25rem)]"
                        >
                          {label}
                        </SelectItem>
                      ))}
                  </SelectGroup>
                </SelectContent>
              </Select>
            </Field>
            <Field className="col-span-2">
              <div className="flex items-center gap-1">
                <FieldLabel id="feedback-work-subagents-label">
                  Subagents
                </FieldLabel>
                <FeedbackInfo
                  label="About subagents"
                  onOpenChange={(open) => {
                    guidanceOpen.current = open;
                  }}
                >
                  Allows up to two helpers with the same model, reasoning and
                  restricted permissions. Codex decides when they help. Parallel
                  work can use more tokens.
                </FeedbackInfo>
              </div>
              <ToggleGroup
                type="single"
                value={draft.subagents}
                disabled={busy}
                aria-labelledby="feedback-work-subagents-label"
                className="grid grid-cols-2 justify-start gap-2"
                onValueChange={(value) => {
                  if (value)
                    setDraft({
                      ...draft,
                      subagents: value as FeedbackReviewDraft["subagents"],
                    });
                }}
              >
                <ToggleGroupItem
                  value="off"
                  variant="outline"
                  className="min-h-11"
                >
                  Off
                </ToggleGroupItem>
                <ToggleGroupItem
                  value="auto"
                  variant="outline"
                  className="min-h-11"
                >
                  When useful
                </ToggleGroupItem>
              </ToggleGroup>
            </Field>
          </FieldGroup>
        ) : null}
        <Field>
          <FieldLabel htmlFor="feedback-work-instructions">
            Instructions for Codex
          </FieldLabel>
          <Textarea
            id="feedback-work-instructions"
            value={draft.notes}
            maxLength={5000}
            disabled={busy}
            className="min-h-32 resize-y text-base"
            placeholder="Extra context, constraints, or a different approach…"
            onChange={(event) =>
              setDraft({ ...draft, notes: event.target.value })
            }
          />
        </Field>
      </FieldGroup>
      {mode === "start" ? (
        <p className="text-sm text-muted-foreground">
          Creates a reviewed PR. Merging and deployment stay manual.
        </p>
      ) : null}
      {error ? <FieldError role="alert">{error}</FieldError> : null}
      <div className="flex flex-wrap items-center gap-2">
        <Button
          type="submit"
          disabled={busy || (mode !== "start" && !dirty)}
          className="min-h-11"
        >
          {busy ? (
            <Loader2
              data-icon="inline-start"
              className="animate-spin motion-reduce:animate-none"
            />
          ) : null}
          {busy
            ? mode === "start"
              ? "Starting…"
              : "Saving…"
            : mode === "start"
              ? "Start Codex"
              : "Save context"}
        </Button>
        <Button
          type="button"
          variant="ghost"
          className="min-h-11"
          disabled={busy}
          onClick={() => setMode(null)}
        >
          Cancel
        </Button>
      </div>
    </form>
  );
  const close = (open: boolean) => {
    if (!open && !guard.current) setMode(null);
  };
  const restoreFocus = (event: Event) => {
    event.preventDefault();
    trigger.current?.focus();
  };
  const enter = (event: Event) => {
    event.preventDefault();
    heading.current?.focus();
  };
  // The outer Radix layer can receive document Escape before the nested tooltip.
  const escape = (event: KeyboardEvent) => {
    if (guard.current || guidanceOpen.current) event.preventDefault();
  };
  return (
    <section aria-label="Manage report" className="flex flex-col gap-3">
      <ToggleGroup
        type="single"
        value={review.status}
        disabled={busy || mode !== null || active}
        aria-label="Report status"
        className="grid grid-cols-2 gap-1 rounded-[var(--radius)] border border-border bg-muted/40 p-1 sm:grid-cols-4"
        onValueChange={(status) => {
          if (status && status !== review.status)
            void save({
              ...review,
              status: status as FeedbackReviewDraft["status"],
            });
        }}
      >
        {Object.entries(reviewStatuses).map(([value, label]) => (
          <ToggleGroupItem
            key={value}
            value={value}
            className="min-h-11 rounded-[calc(var(--radius)-0.25rem)] px-3 data-[state=on]:bg-background data-[state=on]:shadow-sm"
          >
            {label}
          </ToggleGroupItem>
        ))}
      </ToggleGroup>
      <div className="flex flex-wrap items-center gap-2">
        <Button
          disabled={
            busy || mode !== null || active || review.status === "closed"
          }
          className="min-h-11"
          onClick={(event) => open("start", event.currentTarget)}
        >
          <Play data-icon="inline-start" />
          Start work
        </Button>
        <Button
          variant="outline"
          disabled={busy || mode !== null || active}
          className="min-h-11"
          onClick={(event) => open("context", event.currentTarget)}
        >
          <MessageSquarePlus data-icon="inline-start" />
          Context
        </Button>
        {busy ? (
          <span
            role="status"
            className="flex items-center gap-2 text-xs text-muted-foreground"
          >
            <Loader2 className="size-4 animate-spin motion-reduce:animate-none" />
            Saving…
          </span>
        ) : saved ? (
          <span role="status" className="text-xs text-muted-foreground">
            Saved
          </span>
        ) : null}
      </div>
      {run ? (
        <div className="flex flex-wrap items-center gap-2 rounded-[var(--radius)] border border-border p-3 text-sm">
          <span role="status" className="mr-auto">
            {
              {
                queued: "Queued",
                running: "Codex is working",
                pr_ready: "PR ready",
                needs_review: "Needs attention",
                failed: "Work failed",
                cancelled: "Stop requested",
              }[run.status]
            }
          </span>
          {run.thread_id ? (
            <Button asChild variant="outline" className="min-h-11">
              <a href={`codex://threads/${encodeURIComponent(run.thread_id)}`}>
                <ExternalLink data-icon="inline-start" />
                Open chat
              </a>
            </Button>
          ) : null}
          {run.pull_request_url ? (
            <Button asChild variant="outline" className="min-h-11">
              <a href={run.pull_request_url} target="_blank" rel="noreferrer">
                View PR
              </a>
            </Button>
          ) : null}
          {active ? (
            <Button
              variant="ghost"
              className="min-h-11"
              disabled={busy}
              onClick={() => void stop()}
            >
              <Square data-icon="inline-start" />
              Stop
            </Button>
          ) : null}
          {!active && run.outcome ? (
            <p className="basis-full text-muted-foreground">{run.outcome}</p>
          ) : null}
        </div>
      ) : null}
      {runError ? (
        <p role="alert" className="text-sm text-destructive">
          {runError}
        </p>
      ) : null}
      {error && !mode ? <FieldError role="alert">{error}</FieldError> : null}
      {mode ? (
        mobile ? (
          <Drawer open onOpenChange={close} dismissible={!busy}>
            <DrawerContent
              className="max-h-[90dvh]"
              onOpenAutoFocus={enter}
              onEscapeKeyDown={escape}
              onCloseAutoFocus={restoreFocus}
            >
              <div className="overflow-y-auto p-5 pb-[calc(1.25rem+env(safe-area-inset-bottom))]">
                {form}
              </div>
            </DrawerContent>
          </Drawer>
        ) : (
          <Dialog open onOpenChange={close}>
            <DialogContent
              onOpenAutoFocus={enter}
              onEscapeKeyDown={escape}
              onCloseAutoFocus={restoreFocus}
            >
              {form}
            </DialogContent>
          </Dialog>
        )
      ) : null}
      {review.revision ? (
        <div className="flex flex-col gap-3">
          <Button
            variant="ghost"
            className="min-h-11 self-start"
            disabled={busy || mode !== null || historyBusy}
            aria-expanded={historyOpen}
            aria-controls="review-history"
            onClick={() => void showHistory()}
          >
            {historyBusy ? (
              <Loader2
                data-icon="inline-start"
                className="animate-spin motion-reduce:animate-none"
              />
            ) : (
              <History data-icon="inline-start" />
            )}
            History
          </Button>
          {historyOpen ? (
            <div id="review-history" className="flex flex-col gap-3">
              {historyError ? (
                <div className="flex items-center gap-2">
                  <p role="alert" className="text-sm text-destructive">
                    {historyError}
                  </p>
                  <Button
                    variant="outline"
                    disabled={historyBusy}
                    onClick={() => void fetchHistory()}
                  >
                    Retry
                  </Button>
                </div>
              ) : history?.length ? (
                history.map((entry) => (
                  <details
                    key={entry.revision}
                    className="rounded-[var(--radius)] border border-border p-3 text-sm"
                  >
                    <summary className="cursor-pointer">
                      {reviewStatuses[entry.review.status]} ·{" "}
                      <time dateTime={entry.created_at}>
                        {new Date(entry.created_at).toLocaleString()}
                      </time>
                    </summary>
                    <div className="flex flex-col gap-2 pt-3">
                      <p>
                        {entry.review.title ? `${entry.review.title} · ` : ""}
                        {entry.review.kind === "bug" ? "Bug" : "Idea"} ·{" "}
                        {feedbackModels[entry.review.model] ?? "Sol 6.1"} ·{" "}
                        {feedbackReasoningLevels[
                          entry.review.reasoningEffort
                        ] ?? "High"}
                        {entry.review.subagents === "auto"
                          ? " · Subagents when useful"
                          : ""}
                      </p>
                      <p className="whitespace-pre-wrap break-words text-muted-foreground">
                        {entry.review.notes || "No context"}
                      </p>
                    </div>
                  </details>
                ))
              ) : !historyBusy ? (
                <p className="text-sm text-muted-foreground">No changes yet</p>
              ) : null}
            </div>
          ) : null}
        </div>
      ) : null}
    </section>
  );
}

"use client";

import { useState, type ReactNode } from "react";
import { Info } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";

/** Hover, keyboard focus and tap all expose the same supplementary guidance. */
export function FeedbackInfo({
  label,
  children,
  onOpenChange,
}: {
  label: string;
  children: ReactNode;
  onOpenChange?: (open: boolean) => void;
}) {
  const [open, setOpenState] = useState(false);
  function setOpen(value: boolean) {
    setOpenState(value);
    onOpenChange?.(value);
  }
  return (
    <TooltipProvider delayDuration={250}>
      <Tooltip open={open} onOpenChange={setOpen}>
        <TooltipTrigger asChild>
          <Button
            type="button"
            variant="ghost"
            size="icon"
            className="size-11 shrink-0"
            aria-label={label}
            onKeyDown={(event) => {
              if (event.key === "Escape" && open) {
                event.preventDefault();
                event.stopPropagation();
                setOpen(false);
              }
            }}
            onClick={(event) => {
              event.preventDefault();
              setOpen(!open);
            }}
          >
            <Info aria-hidden="true" />
          </Button>
        </TooltipTrigger>
        <TooltipContent
          data-feedback-guidance
          className="max-w-64 text-sm leading-5"
          side="bottom"
          onEscapeKeyDown={(event) => {
            event.preventDefault();
            event.stopPropagation();
            setOpen(false);
          }}
        >
          {children}
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
}

import { z } from "zod";

// Matches the pinned feedback runner execution-settings contract.
export const feedbackModels = {
  "gpt-6.1-sol": "Sol 6.1",
  "gpt-6-luna": "Luna 6",
  "gpt-6-astra": "Astra 6",
} as const;

export const reviewStatuses = {
  needs_review: "Needs review",
  planned: "Planned",
  in_progress: "In progress",
  closed: "Closed",
} as const;
export const feedbackReasoningLevels = {
  low: "Low",
  medium: "Medium",
  high: "High",
  xhigh: "Extra high",
  max: "Max",
  ultra: "Ultra",
} as const;
const reasoningSchema = z.enum([
  "low",
  "medium",
  "high",
  "xhigh",
  "max",
  "ultra",
]);
const subagentsSchema = z.enum(["off", "auto"]);
function compatibleReasoning(
  value: { model?: string; reasoningEffort?: string },
  context: z.RefinementCtx,
) {
  if (value.model === "gpt-6-luna" && value.reasoningEffort === "ultra")
    context.addIssue({
      code: z.ZodIssueCode.custom,
      path: ["reasoningEffort"],
      message: "Luna supports reasoning up to Max.",
    });
}
const reviewFieldsSchema = z
  .object({
    title: z.string().max(160),
    kind: z.enum(["bug", "suggestion"]),
    status: z.enum(["needs_review", "planned", "in_progress", "closed"]),
    notes: z.string().max(5000),
    reasoningEffort: reasoningSchema.default("high"),
    subagents: subagentsSchema.default("off"),
    model: z
      .enum(["gpt-6.1-sol", "gpt-6-luna", "gpt-6-astra"])
      .default("gpt-6.1-sol"),
  })
  .strict();
export const reviewDraftSchema =
  reviewFieldsSchema.superRefine(compatibleReasoning);
export const reviewSchema = reviewFieldsSchema
  .extend({
    revision: z.number().int().min(0),
    updatedAt: z.string().nullable(),
  })
  .strict()
  .superRefine(compatibleReasoning);
export const reviewUpdateSchema = reviewFieldsSchema
  .extend({
    model: reviewFieldsSchema.shape.model.removeDefault().optional(),
    reasoningEffort: reasoningSchema.optional(),
    subagents: subagentsSchema.optional(),
    expectedRevision: z.number().int().min(0).max(2147483646),
  })
  .strict()
  .superRefine(compatibleReasoning);
export const reviewStartSchema = reviewFieldsSchema
  .extend({
    expectedRevision: z.number().int().min(0).max(2147483646),
    requestId: z.string().uuid(),
  })
  .strict()
  .superRefine(compatibleReasoning);
export type FeedbackReviewDraft = z.infer<typeof reviewDraftSchema>;
export type FeedbackReview = z.infer<typeof reviewSchema>;
export type FeedbackReviewHistory = {
  revision: number;
  created_at: string;
  review: FeedbackReviewDraft;
};
export function initialReview(kind: "bug" | "suggestion"): FeedbackReview {
  return {
    title: "",
    kind,
    status: "needs_review",
    notes: "",
    model: "gpt-6.1-sol",
    reasoningEffort: "high",
    subagents: "off",
    revision: 0,
    updatedAt: null,
  };
}
export async function saveFeedbackReview(
  id: string,
  draft: FeedbackReviewDraft,
  expectedRevision: number,
): Promise<FeedbackReview> {
  const response = await fetch(`/api/feedback-kit/reports/${id}/review`, {
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ ...draft, expectedRevision }),
    signal: AbortSignal.timeout(20000),
  });
  const body = await response.json();
  if (!response.ok)
    throw new Error(body.error || "Couldn’t save changes. Try again.");
  return reviewSchema.parse(body);
}

import { z } from "zod";
import { reviewSchema, type FeedbackReviewDraft } from "./review";
// Public receipts exclude task text, fence, actor and lease controls.
export const runSchema = z
  .object({
    id: z.string().uuid(),
    status: z.enum([
      "queued",
      "running",
      "pr_ready",
      "needs_review",
      "failed",
      "cancelled",
    ]),
    thread_id: z.string().nullable(),
    review_thread_id: z.string().nullable(),
    pull_request_url: z
      .string()
      .regex(
        /^https:\/\/github\.com\/[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+\/pull\/\d+$/,
      )
      .nullable(),
    outcome: z.string().nullable(),
    created_at: z.string(),
    updated_at: z.string(),
  })
  .strip();
export type FeedbackRun = z.infer<typeof runSchema>;
export const runColumns =
  "id,status,thread_id,review_thread_id,pull_request_url,outcome,created_at,updated_at";
export const runActive = (run: FeedbackRun | null) =>
  run?.status === "queued" || run?.status === "running";
export async function startFeedbackWork(
  id: string,
  draft: FeedbackReviewDraft,
  expectedRevision: number,
  requestId: string,
) {
  const response = await fetch(`/api/feedback-kit/reports/${id}/runs`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ ...draft, expectedRevision, requestId }),
    signal: AbortSignal.timeout(20000),
  });
  const body = await response.json();
  if (!response.ok)
    throw new Error(body.error || "Couldn’t start work. Try again.");
  return z.object({ review: reviewSchema, run: runSchema }).parse(body);
}
export async function loadFeedbackRun(id: string) {
  const response = await fetch(`/api/feedback-kit/reports/${id}/runs`, {
    cache: "no-store",
    signal: AbortSignal.timeout(15000),
  });
  if (!response.ok) throw new Error("Couldn’t check work. Try again.");
  const body = await response.json();
  return runSchema.nullable().parse(body.run);
}
export async function cancelFeedbackWork(id: string, runId: string) {
  const response = await fetch(`/api/feedback-kit/reports/${id}/runs`, {
    method: "DELETE",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ runId }),
    signal: AbortSignal.timeout(20000),
  });
  if (!response.ok) throw new Error("Couldn’t stop work. Try again.");
}
